// Generate a 100-sample 50 Hz sine at 5 kHz
const N = 100, fs = 5000, f0 = 50;
const sig = [];
for (let i = 0; i < N; i++) {
    sig.push(Math.sin(2 * Math.PI * f0 * (i / fs)));
}
msg.payload = { signal: sig };
return msg;

const r = msg.payload || {};
if (r.error) {
    msg.payload = `<div style="color:#ef4444; padding:12px;">SHAP error: ${r.error}</div>`;
    return msg;
}

const sev = (r.predicted_class === 'Pure_Sinusoidal') ? '#22c55e' : '#ef4444';
let rows = '';
for (const f of (r.top_features || [])) {
    const dirArrow = f.direction === 'increase' ? '▲' : '▼';
    const dirColor = f.direction === 'increase' ? '#f59e0b' : '#3b82f6';
    rows += `
    <tr>
        <td style="padding:6px 10px; color:#e2e6f0;">${f.name.replace(/_/g, ' ')}</td>
        <td style="padding:6px 10px; font-family:monospace; color:#e2e6f0; text-align:right;">${(typeof f.value === 'number' ? f.value.toFixed(4) : f.value)} ${f.unit || ''}</td>
        <td style="padding:6px 10px; color:${dirColor}; font-weight:600;">${dirArrow} ${(f.shap || 0).toFixed(3)}</td>
    </tr>`;
}

msg.payload = `
<div style="font-family: -apple-system, sans-serif; background:#1a1d27; border:1px solid #2a2e42; border-radius:10px; padding:16px; color:#e2e6f0; max-width:560px;">
  <div style="font-size:11px; color:#8892aa; text-transform:uppercase; letter-spacing:0.6px; margin-bottom:6px;">SHAP explanation</div>
  <div style="display:flex; align-items:baseline; gap:10px; margin-bottom:10px;">
    <div style="font-size:20px; font-weight:700;">${r.predicted_class}</div>
    <div style="font-size:13px; color:${sev}; font-weight:600;">${(r.confidence || 0).toFixed(1)}%</div>
  </div>
  <div style="font-size:13px; color:#b6bfd0; margin-bottom:12px; line-height:1.45;">${r.summary_sentence || ''}</div>
  <div style="font-size:11px; color:#8892aa; text-transform:uppercase; letter-spacing:0.6px; margin-bottom:4px;">Top contributing features</div>
  <table style="width:100%; border-collapse:collapse; font-size:13px;">${rows}</table>
</div>`;
return msg;
